package com.sabyeguyz.clinic.masterdata; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="master_data",uniqueConstraints=@UniqueConstraint(columnNames={"category","code"})) public class MasterData {
 @Id @GeneratedValue(strategy=GenerationType.SEQUENCE,generator="master_gen") @SequenceGenerator(name="master_gen",sequenceName="master_data_id_seq",allocationSize=1) private Long id; @Column(nullable=false) private String category; @Column(nullable=false) private String code; @Column(nullable=false) private String name; private boolean active=true; @Column(name="created_at") private Instant createdAt=Instant.now(); @Column(name="updated_at") private Instant updatedAt=createdAt;
 protected MasterData(){} public MasterData(String category,String code,String name){update(category,code,name);} public void update(String c,String code,String n){category=c;this.code=code;name=n;updatedAt=Instant.now();} public void deactivate(){active=false;} public void activate(){active=true;} public Long getId(){return id;} public String getCategory(){return category;} public String getCode(){return code;} public String getName(){return name;} public boolean isActive(){return active;}
}
